const SHIP_RNG={cst:5000,rfr:9000,fdr:8000,rfl:15000,fdx:10000,sub:18000,rfx:13000,ro1:14000,ro2:24000,pmx:24000,ppx:28000,eco:30000,npx:30000,vlc:30000,ulc:30000,ult:30000};
