const distF=d=>d<300?.5+d/600:1/(1+(d/13000)**2);
const cargoDistF=d=>d<300?.5+d/600:1/(1+(Math.max(0,d-3000)/20000)**2);
function money(n,short){const s=n<0?"−":"",a=Math.abs(n);
  if(a>=1e9)return s+"฿"+(a/1e9).toFixed(a>=1e10?1:2)+(short?"B":" พันล้าน");
  if(a>=1e6)return s+"฿"+(a/1e6).toFixed(a>=1e8?0:1)+(short?"M":" ล้าน");
  if(a>=1e3&&short)return s+"฿"+(a/1e3).toFixed(0)+"K";
  return s+"฿"+Math.round(a).toLocaleString("en-US")}
