let S=null, tab="home", paused=false, speed=1, sheetFn=null, lastTick=performance.now(), acc=0, dispCash=0, lastFloat=0, seenNews=0;

function load(){try{const t=localStorage.getItem(KEY);if(t)return migrate(JSON.parse(t))}catch(e){}return null}
function save(){try{if(S)localStorage.setItem(KEY,JSON.stringify(S));else localStorage.removeItem(KEY)}catch(e){}}
function migrate(s){
  s.bases??=[s.hub];s.mkt??=null;s.hedge??=null;s.ach??=[];s.autoMx??=true;s.totCargo??=0;
  s.apT??={};s.apY??={};
  s.rivals??=RIVALS.map((n,i)=>({n,v:s.startCap*[1.5,4,12][i]}));
  for(const [n,f] of [["อันดามันแอร์",.8],["เมฆาเวย์",2.5]])if(!s.rivals.some(r=>r.n===n))s.rivals.push({n,v:s.startCap*f});
  for(const r of s.routes){r.from??=s.hub;r.h??=[]}
  for(const r of s.routes.slice()){if(r.kind)continue;r.kind="pax";
    const fr=r.planes.filter(id=>{const p=s.fleet.find(x=>x.id===id);return p&&!model(p.m).seats});if(!fr.length)continue;
    r.planes=r.planes.filter(id=>!fr.includes(id));let cr=s.routes.find(x=>x.kind==="cargo"&&x.from===r.from&&x.dest===r.dest);
    if(!cr){cr={id:s.nid++,kind:"cargo",from:r.from,dest:r.dest,price:r.price,pmode:"auto",cmode:r.cmode,crate:r.crate,planes:[],h:[]};s.routes.push(cr)}
    for(const id of fr){cr.planes.push(id);const p=s.fleet.find(x=>x.id===id);if(p)p.route=cr.id}}
  if(!s.unlocked){const need=new Set([s.hub,...s.bases,...s.routes.map(r=>r.dest),...s.routes.map(r=>r.from)]);
    s.unlocked=REGIONS.filter(R=>R.c.some(c=>need.has(c))).map(R=>R.id)}
  for(const p of s.fleet){p.cond??=100;p.age??=0;p.down??=0;p.off??=(p.id*.37)%1}
  s.today??=blankT();s.blv??={};s.ships??=[];s.lanes??=[];s.totTeu??=0;s.pbr??=Object.fromEntries([...new Set(s.lanes.map(l=>l.from))].map(c=>[c,1]));s.livery??={tail:"#D47A22",stripe:"#2A5B9C",body:"white",logo:"bird"};
  return s}

