function newGame(){
  S=migrate({name:fate.name,code:fate.code,hub:fate.hub,cash:fate.cap,startCap:fate.cap,fuel:fate.fuel,day:0,rep:50,service:1,loan:0,
     fleet:[],routes:[],events:[],news:[],hist:[{d:0,c:fate.cap,r:0,x:0}],nid:1,goal:0,neg:0,over:false,last:null,totPax:0});
  S.unlocked=[regionOf(S.hub).id];S.prog=[];S.progDay=-1;dispCash=S.cash;view=null;camMode="world";
  addNews(`${S.name} เปิดกิจการที่ ${city(S.hub).n} ด้วยทุน ${money(S.cash)} แผนที่ภูมิภาค${regionOf(S.hub).n}ปลดล็อกแล้ว ซื้อเครื่องบินลำแรกในแท็บฝูงบินได้เลย`);
  paused=false;tab="fleet";save();renderApp();
}

/* ---------- simulation ---------- */
const plane=id=>S.fleet.find(p=>p.id===id);
const rkind=r=>r.kind||"pax";
const fitsKind=(m,r)=>rkind(r)==="cargo"?!m.seats:!!m.seats;
const fno=r=>{const k=rkind(r),L=S.routes.filter(x=>rkind(x)===k),i=L.indexOf(r);return `${S.code} ${(k==="cargo"?800:100)+Math.max(0,i)*2+1}`};
/* R&D centre: permanent company upgrades bought with cash. [id, icon, name, what it changes, step per level, base cost] */
const PERKS=[["fuel","⛽","เครื่องยนต์ประหยัดน้ำมัน","ค่าน้ำมันเครื่องบินและเรือ",-.03,60e6,"น้ำมัน"],
 ["pax","💺","โปรแกรมสะสมไมล์","จำนวนคนที่อยากบินกับเรา",.04,50e6,"ผู้โดยสาร"],
 ["cargo","📦","ศูนย์กระจายสินค้า","รายได้ค่าขนสินค้าและค่าระวางเรือ",.04,45e6,"สินค้า"],
 ["fee","🤝","ดีลสนามบินและท่าเรือ","ค่าธรรมเนียมสนามบินและท่าเรือ",-.04,40e6,"ค่าลงจอด"]];
const PERK_MAX=5,pkDef=id=>PERKS.find(x=>x[0]===id),pkLv=id=>(S&&S.perk&&S.perk[id])||0,pk=id=>1+pkDef(id)[4]*pkLv(id),pkCost=id=>Math.round(pkDef(id)[5]*Math.pow(2.1,pkLv(id))/1e6)*1e6;
const pkPips=id=>`<span class="pkd">${Array.from({length:PERK_MAX},(_,i)=>`<i class="${i<pkLv(id)?"on":""}"></i>`).join("")}</span>`;
const fuelNow=()=>S.hedge&&S.hedge.until>S.day?S.hedge.price:S.fuel;
const mktMult=()=>S.mkt&&S.mkt.until>S.day?S.mkt.mult:1;
const CN_HUBS=["PEK","PVG","CAN","SZX","CTU","KMG","XMN","HKG","MFM"];
function gameDate(){const x=new Date(START);x.setDate(x.getDate()+S.day);return x}
// Cargo seasons from the game calendar
function cargoSeasons(code){const d=gameDate(),mo=d.getMonth(),dd=d.getDate(),out=[];
  if(regionOf(code).id==="th"&&mo>=4&&mo<=6)out.push(["ฤดูผลไม้ไทย",1.35]);
  if(CN_HUBS.includes(code)&&mo===10&&dd>=5&&dd<=15)out.push(["ช้อปปิ้ง 11.11",1.8]);
  if(mo===11&&dd<=20)out.push(["ส่งของขวัญปลายปี",1.25]);
  return out}
const seasonMult=code=>cargoSeasons(code).reduce((a,x)=>a*x[1],1);
function evCargo(c){let m=1;for(const e of S.events)if(e.city===c&&e.until>S.day&&e.cmult)m*=e.cmult;return m}
/* Cargo kinds. Air: parcels / food (rice, meat, fruit) / parts & vehicles. Each kind pays a different rate and fills a
   different share of an aircraft's payload. Sea uses the same three kinds as its box / reefer / ro-ro trades (d / r / o). */
const CK=["pcl","fd","pt"],CK_E={pcl:"📦",fd:"🍎",pt:"🚗"},CK_N={pcl:"พัสดุ",fd:"อาหาร",pt:"ชิ้นส่วน/รถ"},CK_LONG={pcl:"พัสดุและของทั่วไป",fd:"อาหาร ข้าว เนื้อ ผลไม้",pt:"ชิ้นส่วนและรถยนต์"};
const CK_RATE={pcl:1,fd:1.35,pt:1.2},CK_LOAD={pcl:1,fd:.9,pt:.75};
// freight-only routes: more freight per kind, since each freighter now carries a single kind (keeps a lone freighter as viable as before)
let CARGO_KIND_X=1.8;
const SPEC_AIR={a124:"pt"};   // specialised freighters carry one kind only (An-124: outsize parts and vehicles)
const SEA_K={pcl:"d",fd:"r",pt:"o"},K_SEA={d:"pcl",r:"fd",o:"pt"},SEA_LOAD={d:1,r:.6,o:.5},SEA_RATE={d:1,r:1.8,o:1.5};
// share of each kind in a city pair's air freight: food-heavy in SE Asia, Oceania and South America, parts in East Asia, Europe, North America
function ckShare(r){const s={pcl:.5,fd:.28,pt:.22},RG=[regionOf(r.from).id,regionOf(r.dest).id];
  if(RG.some(x=>["th","sea","sam","oc"].includes(x)))s.fd+=.1;if(RG.some(x=>["ea","eu","na"].includes(x)))s.pt+=.08;
  for(const [n] of cargoSeasons(r.from).concat(cargoSeasons(r.dest))){if(n.includes("ผลไม้"))s.fd+=.15;else s.pcl+=.12}
  for(const k of ["fd","pt"])if(!ckOpen(k)){s.pcl+=s[k];s[k]=0}
  const t=s.pcl+s.fd+s.pt;return {pcl:s.pcl/t,fd:s.fd/t,pt:s.pt/t}}
const cbkObj=r=>{if(!r.cbk||typeof r.cbk!=="object")r.cbk={pcl:+(r.cbk||0),fd:0,pt:0};return r.cbk};
const isSpecAir=m=>!!SPEC_AIR[m.id];
// what an aircraft carries: passenger jets carry a mix of all kinds in the belly ("mix"); freighters carry their set kind (auto = chosen each day)
const planeK=p=>{const m=model(p.m);if(m.seats)return "mix";if(SPEC_AIR[m.id])return SPEC_AIR[m.id];return p.ck&&p.ck!=="auto"?p.ck:(p.cka||"pcl")};
// auto freighters: each picks the kind whose unmet demand (incl. waiting stock) pays most, biggest aircraft first
function autoAssign(r,dk,d){const ps=r.planes.map(plane).filter(p=>p&&!model(p.m).seats&&!isSpecAir(model(p.m))&&(!p.ck||p.ck==="auto"));if(!ps.length)return;
  const B=cbkObj(r),res={};for(const t of CK)res[t]=dk[t]+(B[t]||0);
  const sh0=ckShare(r);for(const id of r.planes){const p=plane(id);if(!p||ps.includes(p))continue;const m=model(p.m),t=planeK(p);if(t==="mix"){for(const k of CK)res[k]-=legsFor(m,d)*m.cargo*sh0[k]}else res[t]-=legsFor(m,d)*m.cargo*CK_LOAD[t]}
  for(const p of ps.slice().sort((a,b)=>model(b.m).cargo-model(a.m).cargo)){const m=model(p.m),L=legsFor(m,d);let bt="pcl",bv=-Infinity;
    for(const t of CK){if(!ckOpen(t))continue;const v=res[t]>0?Math.min(res[t],L*m.cargo*CK_LOAD[t])*CK_RATE[t]:res[t]*1e-6;if(v>bv+1e-12){bv=v;bt=t}}p.cka=bt;res[bt]-=L*m.cargo*CK_LOAD[bt]}}
// ships: reefers and car carriers are specialised; every other ship is a combined ship carrying one chosen kind at a time
const shipSpec=m=>!!(m.reefer||m.roro);
const shipK=(sh,m)=>m.reefer?"r":m.roro?"o":(sh.ck&&sh.ck!=="auto"?sh.ck:(sh.cka||"d"));
const shipLoadF=(m,k)=>shipSpec(m)?1:SEA_LOAD[k];
function laneAutoAssign(l,DK,km){const ss=l.ships.map(shipById).filter(sh=>sh&&!shipSpec(shipM(sh.m))&&(!sh.ck||sh.ck==="auto"));if(!ss.length)return;
  const B=l.bk||{},res={};for(const k of ["d","r","o"])res[k]=DK[k]+(B[k]||0)*.2;
  for(const id of l.ships){const sh=shipById(id);if(!sh||ss.includes(sh))continue;const m=shipM(sh.m),k=shipK(sh,m);res[k]-=m.teu*shipLoadF(m,k)/legDaysS(m,km)}
  for(const sh of ss.slice().sort((a,b)=>shipM(b.m).teu-shipM(a.m).teu)){const m=shipM(sh.m),Ld=legDaysS(m,km);let bk="d",bv=-Infinity;
    for(const k of ["d","r","o"]){if(!skOpen(k))continue;const v=res[k]>0?Math.min(res[k],m.teu*SEA_LOAD[k]/Ld)*SEA_RATE[k]:res[k]*1e-6;if(v>bv+1e-12){bv=v;bk=k}}sh.cka=bk;res[bk]-=m.teu*SEA_LOAD[bk]/Ld}}
const AIR_OPTS=[["auto","🤖 อัตโนมัติ"],["pcl","📦 พัสดุ"],["fd","🍎 อาหาร"],["pt","🚗 ชิ้นส่วน/รถ"]];
const SEA_OPTS=[["auto","🤖 อัตโนมัติ"],["d","📦 พัสดุ · เต็มลำ"],["r","🍎 อาหาร · 60%"],["o","🚗 ชิ้นส่วน/รถ · 50%"]];
const ckSel=(attr,id,val,opts)=>`<select class="cksel" data-${attr}="${id}">${opts.filter(([v])=>v==="auto"||(attr==="sck"?skOpen(v):ckOpen(v))||v===val).map(([v,n])=>`<option value="${v}" ${(val||"auto")===v?"selected":""}>${n}</option>`).join("")}</select>`;
const kindChip=t=>`<span class="kchip k-${t}">${CK_E[t]} ${CK_N[t]}</span>`;
/* Advice for a route's freight mix: switch an aircraft from a kind that has spare room to one that is short,
   or buy one more freighter for the most valuable shortfall. Returns {html, act} where act is applied by the button. */
function airAdvice(r,c){const d=c.d,B=cbkObj(r),short={},over={};
  for(const t of CK){const k=c.cK[t];short[t]=k.dem+(B[t]||0)*.2-k.cap;over[t]=k.cap-k.dem}
  const need=CK.filter(t=>short[t]>Math.max(3,c.cK[t].dem*.08)).sort((a,b)=>short[b]*CK_RATE[b]-short[a]*CK_RATE[a]);
  if(!need.length)return {html:`✅ ขนครบทุกประเภทแล้ว ไม่มีสินค้าตกค้าง`};
  let best=null;
  for(const id of r.planes){const p=plane(id);if(!p)continue;const m=model(p.m);if(m.seats||isSpecAir(m)||!p.ck||p.ck==="auto")continue;
    const L=legsFor(m,d),k=p.ck,mine=(c.plan.get(p.id)||L)*m.cargo*CK_LOAD[k];if(over[k]<mine*.5)continue;   // legs actually flown today (trimmed when its kind is oversupplied)
    for(const t of need){if(t===k)continue;const v=Math.min(short[t],L*m.cargo*CK_LOAD[t])*CK_RATE[t]-Math.max(0,mine-over[k])*CK_RATE[k];if(v>0&&(!best||v>best.v))best={v,p,t,from:k}}}
  if(best)return {html:`💡 ${CK_E[best.t]} ${CK_N[best.t]}ยังขาด ~${Math.round(short[best.t])} ตัน/วัน แต่ ${CK_E[best.from]} ${CK_N[best.from]}เหลือที่ว่าง · แนะนำเปลี่ยน <b>${best.p.reg}</b> ไปขน${CK_N[best.t]}`,act:{plane:best.p.id,ck:best.t},btn:"ใช้คำแนะนำ"};
  const autoN=r.planes.map(plane).filter(p=>p&&!model(p.m).seats&&!isSpecAir(model(p.m))&&(!p.ck||p.ck==="auto")).length;
  const t=need[0],opts=MODELS.filter(m=>!m.seats&&m.range>=d&&(!isSpecAir(m)||SPEC_AIR[m.id]===t)).map(m=>({id:m.id,m,price:priceFor(m),v:planeGain(r,m.id)})).filter(o=>o.v&&o.v.gain>0);
  const bdA=valueBadges(opts),o=opts.find(x=>x.id===bdA.fast);
  return {html:`💡 ${CK_E[t]} ${CK_N[t]}ยังขาด ~${Math.round(short[t])} ตัน/วัน${autoN?" ทั้งที่เครื่องอัตโนมัติขนเต็มแล้ว":" และเครื่องทุกลำขนเต็มแล้ว"}${o?` · แนะนำซื้อ <b>${o.m.name}</b> เพิ่ม 1 ลำ ตั้งให้ขน${CK_N[t]} (กำไรเพิ่ม ~${money(o.v.gain,true)}/วัน คืนทุน ${o.v.pay} วัน)`:" · ยังไม่มีเครื่องรุ่นไหนเพิ่มแล้วคุ้ม"}`,act:o?{buy:1}:null,btn:o?"ไปที่ซื้อเครื่อง":null}}
function seaAdvice(l,c){const B=l.bk||{},short={},over={};
  for(const k of ["d","r","o"]){short[k]=c.DK[k]+(B[k]||0)*.2-c.capK[k];over[k]=c.capK[k]-c.DK[k]}
  const need=["d","r","o"].filter(k=>short[k]>Math.max(3,c.DK[k]*.08)).sort((a,b)=>short[b]*SEA_RATE[b]-short[a]*SEA_RATE[a]);
  if(!need.length)return {html:`✅ ขนครบทุกประเภทแล้ว ไม่มีตู้ตกค้าง`};
  let best=null;
  for(const id of l.ships){const sh=shipById(id);if(!sh)continue;const m=shipM(sh.m);if(shipSpec(m)||!sh.ck||sh.ck==="auto")continue;
    const Ld=legDaysS(m,c.km),k=sh.ck,mine=m.teu*SEA_LOAD[k]/Ld;if(over[k]<mine*.5)continue;
    for(const t of need){if(t===k)continue;const v=Math.min(short[t],m.teu*SEA_LOAD[t]/Ld)*SEA_RATE[t]-Math.max(0,mine-over[k])*SEA_RATE[k];if(v>0&&(!best||v>best.v))best={v,sh,t,from:k}}}
  const N=k=>CK_N[SEA_KN[k]],E=k=>CK_E[SEA_KN[k]];
  if(best)return {html:`💡 ${E(best.t)} ${N(best.t)}ยังขาด ~${Math.round(short[best.t])} ตู้/วัน แต่ ${E(best.from)} ${N(best.from)}เหลือที่ว่าง · แนะนำเปลี่ยน <b>${best.sh.reg}</b> ไปขน${N(best.t)}`,act:{ship:best.sh.id,ck:best.t},btn:"ใช้คำแนะนำ"};
  const t=need[0],opts=SHIPS.filter(m=>shipSpec(m)?(m.reefer?"r":"o")===t:true).map(m=>({id:m.id,m,price:m.price,v:shipGain(l,m.id)})).filter(o=>o.v&&o.v.gain>0),bdS=valueBadges(opts),o=opts.find(x=>x.id===bdS.fast);
  return {html:`💡 ${E(t)} ${N(t)}ยังขาด ~${Math.round(short[t])} ตู้/วัน และเรือทุกลำขนเต็มแล้ว${o?` · แนะนำซื้อ <b>${o.m.name}</b> เพิ่ม 1 ลำ${shipSpec(o.m)?"":" ตั้งให้ขน"+N(t)} (กำไรเพิ่ม ~${money(o.v.gain,true)}/วัน คืนทุน ${o.v.pay} วัน)`:" · ยังไม่มีเรือลำไหนเพิ่มแล้วคุ้ม"}`,act:o?{buy:1}:null,btn:o?"ไปที่ซื้อเรือ":null}}
const adviceBox=a=>`<div class="advice"><span>${a.html}</span>${a.btn?`<button class="btn sm primary" id="advgo">${a.btn}</button>`:""}</div>`;
