function nextCel(){if(!cel.length){celBusy=false;return}celBusy=true;
  const seen=new Set(),batch=cel.splice(0,6).filter(([k,t])=>!seen.has(k+t)&&seen.add(k+t)).slice(0,4),lab=k=>k.startsWith("!")?k.slice(1):"ปลดล็อก"+k,short=k=>k.startsWith("!")?k.slice(1).replace(/[!]/g,""):k;
  const d=document.createElement("div");d.className="unlock"+(batch.length>1?" multi":"");
  d.innerHTML=batch.length===1?`<div class="eyebrow">${esc(lab(batch[0][0]))}</div><b>${esc(batch[0][1])}</b>`
    :`<div class="eyebrow">🎉 ปลดล็อก ${batch.length} อย่าง</div><ul>${batch.map(([k,t])=>`<li><b>${esc(t)}</b><span class="muted">${esc(short(k))}</span></li>`).join("")}</ul>`;
  document.body.appendChild(d);confetti(innerWidth/2,innerHeight*.16);
  d.insertAdjacentHTML("beforeend",`<button class="celoff" type="button">ไม่ต้องแสดงป๊อปอัปแบบนี้อีก</button>`);
  const done=()=>{if(!d.isConnected)return;d.remove();nextCel()};d.onclick=done;
  d.querySelector(".celoff").onclick=e=>{e.stopPropagation();S.celOff=true;cel.length=0;save();d.remove();celBusy=false;toast("ปิดป๊อปอัปปลดล็อกแล้ว · เปิดใหม่ได้ที่เมนู ⋯");updCelBtn()};
  setTimeout(done,reduce?1800:batch.length>1?3600:2600)}
