function mapTap(mx,my){
  const rg=mapHits.find(h=>h.reg&&Math.abs(h.px-mx)<h.hw&&Math.abs(h.py-my)<14);
  if(rg){openSheet(regionSheet({id:rg.reg}));return}
  let best=null,bd=22;for(const h of mapHits){if(!h.c)continue;const d=Math.hypot(h.px-mx,h.py-my);if(d<bd){bd=d;best=h}}
  let bp=null,bpd=16;for(const h of mapHits){if(!h.port)continue;const d=Math.hypot(h.px-mx,h.py-my);if(d<bpd){bpd=d;bp=h}}
  if(bp&&(vmode()==='sea'||!best||bpd+4<bd)){selCity=null;refreshAirports();showPop({type:"port",id:bp.port,x:mx,y:my});return}
  if(best){selCity=best.c;refreshAirports();showPop({type:"ap",id:best.c,x:mx,y:my});return}
  const rt=vmode()==="sea"?null:routeAt(mx,my);if(rt){selCity=null;refreshAirports();showPop({type:"route",id:rt,x:mx,y:my});return}
  const ln=vmode()==="air"?null:laneAt(mx,my);if(ln){selCity=null;refreshAirports();showPop({type:"lane",id:ln,x:mx,y:my});return}
  selCity=null;closePop();refreshAirports()}
function laneAt(mx,my){let best=null,bd=16;
  for(const [id,o] of laneScrG){const P=o.scr;for(let i=1;i<P.length;i++){const [x1,y1]=P[i-1],[x2,y2]=P[i],dx=x2-x1,dy=y2-y1,L2=dx*dx+dy*dy||1,t=clamp(((mx-x1)*dx+(my-y1)*dy)/L2,0,1),d=Math.hypot(mx-(x1+t*dx),my-(y1+t*dy));if(d<bd){bd=d;best=id}}}
  return best}
function routeAt(mx,my){let best=null,bd=16;
  for(const [id,a] of routeArcs){const P=a.out;for(let i=1;i<P.length;i++){const [x1,y1]=P[i-1],[x2,y2]=P[i],dx=x2-x1,dy=y2-y1,L2=dx*dx+dy*dy||1,t=clamp(((mx-x1)*dx+(my-y1)*dy)/L2,0,1),d=Math.hypot(mx-(x1+t*dx),my-(y1+t*dy));if(d<bd){bd=d;best=id}}}
  return best}
