    if(gain>0&&Date.now()-(afk.pt||0)>2200){afk.pt=Date.now();afk.lc=S.cash;const pl=$("#afkplus");if(pl){pl.textContent="+"+money(gain,true);pl.classList.remove("go");void pl.offsetWidth;pl.classList.add("go")}}
