function computeRating(){const L=S.last||{},out={};
  const act=S.routes.filter(r=>r.planes.length),fl=S.fleet.filter(p=>p.route);
  if(act.length){const cond=fl.length?fl.reduce((a,p)=>a+p.cond,0)/fl.length:100,lf=L.lf||0,dests=new Set(act.map(r=>r.dest)).size;
    const net=clamp(Math.log2(1+dests)/Math.log2(41),0,1),lfS=clamp(1-Math.abs(lf-.85)/.45,0,1),cS=clamp((cond-40)/55,0,1),prof=act.filter(r=>r.last&&r.last.profit>0).length/act.length;
    out.air={v:5*(.3*net+.25*lfS+.2*cS+.25*prof),tip:net<.5?"เปิดเส้นทางไปเมืองใหม่ ๆ เพิ่ม":lfS<.6?"ปรับราคาให้ที่นั่งเต็มราว 85%":cS<.6?"ส่งเครื่องบินเข้าซ่อมบำรุง":prof<.7?"แก้เส้นทางที่ขาดทุน":"ยอดเยี่ยม รักษาไว้"}}
  const ln=S.lanes.filter(l=>l.ships.length);
  if(ln.length){const ld=ln.reduce((a,l)=>{const c=laneCalc(l);return a+Math.max(c.load,c.loadr)},0)/ln.length,prof=ln.filter(l=>laneAvg(l)>0).length/ln.length,
      size=clamp(Math.log2(1+S.ships.length)/Math.log2(21),0,1),br=clamp(pbList().reduce((a,c)=>a+pbl(c),0)/9,0,1);
    out.sea={v:5*(.3*clamp(ld/.9,0,1)+.3*prof+.25*size+.15*br),tip:ld<.6?"เรือว่างเยอะ ลดจำนวนเรือหรือใช้เรือเล็กลง":prof<.7?"แก้เส้นทางเรือที่ขาดทุน":size<.5?"เพิ่มกองเรือและเส้นทางเรือ":"กองเรือแข็งแรงมาก"}}
  const cr=S.routes.map(r=>r.last).filter(c=>c&&c.ccap>0);
  if(cr.length){const cap=cr.reduce((a,c)=>a+c.ccap,0),done=cr.reduce((a,c)=>a+(c.cargo||0),0),ld=cap?done/cap:0,fr=S.fleet.filter(p=>!model(p.m).seats).length,vol=clamp(Math.log10(1+(L.cargo||0))/3.3,0,1);
    out.cargo={v:5*(.4*clamp(ld/.85,0,1)+.35*vol+.25*clamp(fr/6,0,1)),tip:ld<.6?"ระวางว่าง ลองลดค่าระวาง":fr<2?"ซื้อเครื่องขนสินค้าเพิ่ม":vol<.6?"เพิ่มเส้นทางขนสินค้า":"ศูนย์ขนส่งสินค้าชั้นนำ"}}
  if(act.length){const svcAvg=act.reduce((a,r)=>a+svcOf(r),0)/act.length,fair=act.reduce((a,r)=>{const c=r.last||calc(r);return a+clamp(1.25-(c.price/c.base-.75)*.9,0,1)},0)/act.length,
      crowd=clamp(1-Math.max(0,(L.lf||0)-.92)*6,0,1),bd=S.news.slice(0,10).filter(n=>n.d>=S.day-7&&/ขัดข้อง|หยุดงาน/.test(n.t)).length;
    out.pax={v:5*(.4*S.rep/100+.2*svcAvg/2+.25*fair+.15*crowd)-Math.min(1,bd*.3),tip:S.rep<55?"เพิ่มระดับบริการเพื่อดันชื่อเสียง":fair<.6?"ตั๋วแพงไป ลองลดราคาบางเส้นทาง":crowd<.8?"เครื่องเต็มแน่นเกิน เพิ่มเที่ยวบิน":"ผู้โดยสารรักสายการบินนี้"}}
  for(const k in out)out[k].v=clamp(out[k].v,0,5);
  const ks=Object.keys(out),overall=ks.length?ks.reduce((a,k)=>a+out[k].v,0)/ks.length:0;
  const prev=S.rating&&S.rating.overall;S.rating={overall,cats:out};
  if(prev!=null){const a=Math.floor(prev*2)/2,b=Math.floor(overall*2)/2;if(b>a&&b>=1)celebrate("เรตติ้งใหม่",`${b.toFixed(1)} ดาว`);else if(b<a)addNews(`⭐ เรตติ้งสายการบินลดลงเหลือ ${overall.toFixed(1)} ดาว`)}}
const starMult=()=>S&&S.rating?.9+.04*S.rating.overall:1;
function starsHTML(v,size){const out=[];for(let i=0;i<5;i++){const f=clamp(v-i,0,1);out.push(`<i>★<b style="width:${f*100}%">★</b></i>`)}return `<span class="stars5" style="${size?`font-size:${size}px`:""}" aria-label="${v.toFixed(1)} ดาว">${out.join("")}</span>`}
function rivalStars(rv){rv.st??=+(3+Math.random()*1.4).toFixed(1);return rv.st}
function ratingHTML(){const R=S.rating;if(!R||!has("rank"))return "";const cats=RCATS.map(([k,n,e])=>{const c=R.cats[k];return `<div class="rrow"><span>${e} ${n}</span>${c?starsHTML(c.v,13):'<span class="muted small">ยังไม่เริ่ม</span>'}<span class="num">${c?c.v.toFixed(1):"–"}</span></div>`}).join("");
  const weakest=Object.entries(R.cats).sort((a,b)=>a[1].v-b[1].v)[0];
  return `<div class="panel stack"><div class="row between"><span class="eyebrow">⭐ เรตติ้งสายการบิน</span><span class="muted small">ผู้โดยสาร ${R.overall>=2.5?"+":""}${Math.round((starMult()-1)*100)}% จากเรตติ้ง</span></div>
   <div class="rating"><div class="rbig"><div class="n">${R.overall.toFixed(1)}</div>${starsHTML(R.overall,17)}<div class="muted small">โดยรวม</div></div><div class="rsub">${cats}</div></div>
   ${weakest?`<div class="rtip">💡 ด้านที่ควรพัฒนา: <b>${RCATS.find(x=>x[0]===weakest[0])[1]}</b> · ${weakest[1].tip}</div>`:`<div class="rtip">เริ่มบินหรือเดินเรือเพื่อรับเรตติ้งแรก</div>`}${voiceHTML()}</div>`}
let brReg=null,brSeg="air";
function branchHTML(){if(bm()!=="cargo"||!has("sea"))brSeg="air";const seg=bm()!=="cargo"||!has("sea")?"":`<div class="seg"><button data-brseg="air" class="${brSeg==="air"?"on":""}">✈ สาขาสนามบิน <span class="num muted small">${S.bases.length}</span></button><button data-brseg="sea" class="${brSeg==="sea"?"on":""}">⚓ สาขาท่าเรือ <span class="num muted small">${pbList().length}</span></button></div>`;
  return seg+(brSeg==="sea"?portBranchHTML():airBranchHTML())}
function portBranchHTML(){
  const mine=pbList().map(code=>{const pt=port(code),ls=S.lanes.filter(l=>l.from===code||l.to===code),sh=ls.reduce((a,l)=>a+l.ships.length,0),pf=ls.filter(l=>l.from===code).reduce((a,l)=>a+laneAvg(l),0),lv=pbl(code);
    return `<div class="brcard" style="border-left-color:var(--port)"><div class="row between" style="align-items:flex-start"><div style="min-width:0"><div class="row" style="gap:8px"><span style="font-family:var(--f-display);font-weight:700;font-size:18px">⚓ ${pt.n}</span><span class="stars">${"★".repeat(lv)}${"☆".repeat(BR_MAX-lv)}</span></div>
      <div class="small muted">${REGIONS.find(R=>R.id===pt.reg).n}${pt.deep?" · ท่าเรือน้ำลึก":""}</div></div><button class="btn sm" data-pbroute="${code}">+ เส้นทางเรือ</button></div>
      <div class="kv" style="grid-template-columns:repeat(3,1fr)"><div><div class="k">เส้นทางเรือ</div><div class="v">${ls.length}</div></div><div><div class="k">เรือ</div><div class="v">${sh}</div></div><div><div class="k">กำไร/วัน</div><div class="v ${pf<0?"bad":"good"}">${money(pf,true)}</div></div></div>
      <div class="small muted">ตู้สินค้า +${Math.round((pBoost(code)-1)*100)}% · ค่าท่าเรือ −${Math.round(15*(lv-1))}% · ค่าดูแล ${money(pBranchUpkeep(code),true)}/วัน</div>
      <div class="row">${lv<BR_MAX?`<button class="btn sm ${S.cash>=pBranchUp(code)?"primary":""}" style="flex:1" data-pbup="${code}" ${S.cash>=pBranchUp(code)?"":"disabled"}>อัปเกรดเป็นระดับ ${lv+1} · ${money(pBranchUp(code),true)}</button>`:`<span class="small good" style="flex:1">ระดับสูงสุดแล้ว</span>`}
      <button class="btn sm danger" data-pbclose="${code}" ${S.lanes.some(l=>l.from===code)?"disabled":""}>ปิดสาขา</button></div></div>`}).join("");
  const reg=brReg&&REGIONS.find(R=>R.id===brReg)||REGIONS.find(R=>R.id===regionOf(S.hub).id);
  const cand=PORTS.filter(pt=>pt.reg===reg.id&&!pbl(pt.c)).sort((a,b)=>b.w-a.w),open=S.unlocked.includes(reg.id);
  return `<div class="row between"><h2>สาขาท่าเรือ <span class="muted num small">${pbList().length} แห่ง</span></h2><span class="muted small">เรือทุกลำต้องออกจากสาขาท่าเรือ</span></div>
  ${mine?`<div class="brgrid">${mine}</div>`:`<div class="panel small muted">ยังไม่มีสาขาท่าเรือ เปิดสาขาแรกด้านล่าง แล้วไปซื้อเรือในแท็บสินค้า</div>`}
  <div class="row between" style="margin-top:6px"><h2>เปิดสาขาท่าเรือใหม่</h2><span class="muted small">ท่าเรือ ${PORTS.length} แห่ง</span></div>
  <div class="seg scrollx">${REGIONS.map(R=>{const n=PORTS.filter(pt=>pt.reg===R.id).length;return n?`<button data-brreg="${R.id}" class="${R===reg?"on":""}">${S.unlocked.includes(R.id)?"":"🔒 "}${R.n} <span class="num muted" style="font-size:11px">${n}</span></button>`:""}).join("")}</div>
  ${open?"":`<div class="panel row between"><span class="small">ภูมิภาค${reg.n}ยังล็อกอยู่</span><button class="btn sm primary" data-brunlock="${reg.id}">ปลดล็อก ${money(regionCost(reg),true)}</button></div>`}
  <div class="pick">${cand.map(pt=>{const cost=pBranchCost(pt.c);return `<button data-pbopen="${pt.c}" ${!open||S.cash<cost?"disabled":""}><span class="iata" style="font-size:12px">${pt.c.slice(2)}</span><span>${pt.n}<br><span class="muted" style="font-size:12.5px">ปริมาณตู้ ${"●".repeat(Math.max(1,Math.round(pt.w/4)))}${pt.deep?" · น้ำลึก":""} · ค่าดูแล ${money(120e3+pt.w*20e3,true)}/วัน</span></span><span class="num small" style="font-weight:600;color:${open&&S.cash>=cost?"var(--accent)":"var(--muted)"}">${open?money(cost,true):"🔒"}</span></button>`}).join("")||'<div class="muted small">ไม่มีท่าเรือให้เปิดในภูมิภาคนี้แล้ว</div>'}</div>
  <div class="muted small">สาขาท่าเรือแพงขึ้น 30% ต่อสาขาที่มีอยู่ · อัปเกรดเพิ่มตู้สินค้า 8% และลดค่าท่าเรือ 15% ต่อระดับ</div>`}
/* What people at one of your airports (hub or branch) want: top destinations by passengers a day,
   and how each is served — happy, short of seats, wished-for, or in a locked region. Cached per day. */
let wishCache={k:"",m:new Map()};
function wishesOf(code){const key=S.day+":"+S.routes.length+":"+S.unlocked.join()+":"+S.rep.toFixed(0);if(wishCache.k!==key)wishCache={k:key,m:new Map(),all:new Map()};
  if(wishCache.m.has(code))return wishCache.m.get(code);
  const a=city(code),out=[];
  if(aptTakes(code,"pax"))for(const b of CITIES){if(b.c===code||!aptTakes(b.c,"pax"))continue;const d=dist(a,b);if(d<150)continue;
    const dem=calc({id:-9,kind:"pax",from:code,dest:b.c,price:baseFare(d),pmode:"auto",planes:[],h:[]},baseFare(d)).demand;out.push({c:b,d,dem})}
  out.sort((x,y)=>y.dem-x.dem);wishCache.all.set(code,out);   // places you can fly to now first (4), then the biggest wishes in locked regions (2)
  const top=[...out.filter(w=>isOpen(w.c.c)).slice(0,4),...(has("regions")?out.filter(w=>!isOpen(w.c.c)).slice(0,2):[])].map(w=>{
    const r=S.routes.find(x=>rkind(x)==="pax"&&((x.from===code&&x.dest===w.c.c)||(x.dest===code&&x.from===w.c.c)));
    if(!isOpen(w.c.c))return {...w,st:"lock",R:regionOf(w.c.c)};
    if(!r)return w.d>AIR_MAX("pax")?{...w,st:"far"}:{...w,st:"want"};
    const L=r.last,left=L?Math.max(0,Math.round(L.demand-L.pax)):0;   // a route opened today has no results yet
    return {...w,r,st:!r.planes.length?"idle":!L?"new":left>Math.max(20,L.demand*.15)?"short":"happy",left}});
  wishCache.m.set(code,top);return top}
function wishMood(w){return w.st==="happy"?["😊","พอใจ","good"]:w.st==="short"?["😟",`ที่นั่งไม่พอ · ตกค้าง ~${w.left.toLocaleString()} คน/วัน`,"warn"]:w.st==="idle"?["😐","เปิดเส้นทางแล้วแต่ยังไม่มีเครื่อง","warn"]:w.st==="new"?["🆕","เพิ่งเปิดเส้นทาง รอผลพรุ่งนี้","muted"]:w.st==="far"?["🔗","ไกลเกินบินตรง ต้องต่อเครื่องผ่านสาขา","muted"]:w.st==="lock"?["🔒",`อยากไป แต่${w.R.n}ยังล็อก`,"muted"]:["🙏","อยากให้เปิดเส้นทาง","accent"]}
function wishLine(code){const ws=wishesOf(code),c=city(code),w=ws.find(x=>x.st==="want")||ws.find(x=>x.st==="short")||ws.find(x=>x.st==="lock");
  if(!ws.length)return "";if(!w)return `คน${c.n}พอใจกับเที่ยวบินของเราแล้ว 😊`;
  return w.st==="want"?`คน${c.n}อยากไป<b>${w.c.n}</b>มากที่สุด แต่เรายังไม่มีเที่ยวบิน`:w.st==="short"?`คน${c.n}บ่นว่าเที่ยวบินไป<b>${w.c.n}</b>ที่นั่งไม่พอ`:`คน${c.n}อยากไป<b>${w.c.n}</b> แต่ภูมิภาคนั้นยังล็อกอยู่`}
function wishesHTML(code,n){const ws=wishesOf(code).slice(0,n||6);if(!ws.length)return "";const mx=Math.max(1,...ws.map(w=>w.dem));
  return `<div class="wish"><div class="wish-say">💭 ${wishLine(code)}</div>${ws.map(w=>{const [e,t,cl]=wishMood(w);
    return `<div class="wish-row"><span class="wish-code">${w.c.c}</span><span class="wish-mid"><b>${w.c.n}</b> <span class="muted small">${w.d.toLocaleString()} กม.</span><span class="wish-bar"><i style="width:${Math.max(6,w.dem/mx*100).toFixed(0)}%"></i></span><span class="small ${cl}">${e} ${t}</span></span>
      <span class="wish-end"><b class="num">${Math.round(w.dem).toLocaleString()}</b><small>คน/วัน</small>${w.st==="want"?`<button class="btn sm primary" data-wish="${code}>${w.c.c}">เปิดเส้นทาง</button>`:w.st==="lock"?`<button class="btn sm" data-wunlock="${w.R.id}">ปลดล็อก</button>`:w.st==="short"||w.st==="idle"?`<button class="btn sm" data-wroute="${w.r.id}">ดูเส้นทาง</button>`:""}</span></div>`}).join("")}</div>`}
/* Route opportunities: destinations that people at any of your airports want and you don't serve yet,
   with the profit forecast; best first. */
function oppsList(){const seen=new Set(),out=[];
  for(const code of S.bases)for(const w of wishesOf(code)){if(w.st!=="want")continue;const k=[code,w.c.c].sort().join("-");if(seen.has(k))continue;seen.add(k);
    const fc=routeForecast(code,w.c.c,"pax");out.push({from:code,w,fc,profit:fc.best?fc.best.profit:-1e15})}
  return out.sort((a,b)=>b.profit-a.profit)}
function oppsHTML(){if(rseg!=="pax")return "";const L=oppsList().slice(0,5);if(!L.length)return "";
  return `<div class="opps"><div class="row between"><b>💡 ผู้โดยสารเรียกร้องเส้นทางใหม่</b><span class="muted small">${L.length} เส้นทาง · จากทุกสาขา</span></div>
    ${L.map(({from,w,fc})=>{const b=fc.best;return `<div class="opp"><span class="opp-rt"><b class="num">${from} → ${w.c.c}</b><small>${city(from).n} → ${w.c.n} · ${w.d.toLocaleString()} กม.</small></span>
      <span class="opp-dem"><b class="num">${Math.round(w.dem).toLocaleString()}</b><small>คน/วัน</small></span>
      <span class="opp-pf ${!b?"muted":b.profit>=0?"good":"bad"}"><b class="num">${b?(b.profit>=0?"+":"−")+money(Math.abs(b.profit),true):"—"}</b><small>${b?"กำไร/วัน":"ยังไม่มีเครื่อง"}</small></span>
      <button class="btn sm primary" data-wish="${from}>${w.c.c}">เปิด</button></div>`}).join("")}</div>`}
function bindWishes(){
  $$("[data-wish]").forEach(b=>b.onclick=e=>{e.stopPropagation();const [f,t]=b.dataset.wish.split(">");openSheet(newRouteSheet({from:f,kind:"pax",dest:t}))});
  $$("[data-wunlock]").forEach(b=>b.onclick=e=>{e.stopPropagation();openSheet(regionSheet({id:b.dataset.wunlock}))});
  $$("[data-wroute]").forEach(b=>b.onclick=e=>{e.stopPropagation();openSheet(routeSheet(+b.dataset.wroute,{}))});
  $$("[data-cwish]").forEach(b=>b.onclick=e=>{e.stopPropagation();const [f,t]=b.dataset.cwish.split(">");openSheet(newRouteSheet({from:f,kind:"cargo",dest:t}))});
  $$("[data-lwish]").forEach(b=>b.onclick=e=>{e.stopPropagation();const [f,t]=b.dataset.lwish.split(">");openSheet(newLaneSheet({from:f,to:t}))});
  const rw=()=>{const wp=$("#wishpanel");if(wp){wp.innerHTML=mapWishHTML();bindWishes()}};
  $$("[data-cwm]").forEach(b=>b.onclick=e=>{e.stopPropagation();S.ui_cwm=b.dataset.cwm;save();rw()});
  $$("[data-cwk]").forEach(b=>b.onclick=e=>{e.stopPropagation();S.ui_cwk=b.dataset.cwk;save();rw()})}
