const motif=(d,x,y,z,col,op)=>`<path d="${d}" transform="translate(${(x-z/2).toFixed(2)} ${(y-z/2).toFixed(2)}) scale(${(z/24).toFixed(4)})" fill="${col}"${op!=null?` opacity="${op}"`:""}/>`;
