  {const lr=Math.max(.45,H*.055);g+=`<circle cx="${x0+Lx*.46}" cy="${top-lr*.4}" r="${lr}" fill="#E5322D"/><circle cx="${x0+Lx*.52}" cy="${bot+lr*.3}" r="${lr}" fill="#E5322D"/><circle cx="${x1-H*.02}" cy="${top+H*.42}" r="${lr*.9}" fill="#FFFFFF" stroke="${edge}" stroke-width=".25"/>`}
