    g+=`<path d="M${wx} ${wr}L${tx} ${ty}L${tx+Lx*.03} ${ty+H*.03}L${wx+Lx*.215} ${wr+H*.12}L${wx+Lx*.03} ${wr+H*.15}Q${wx-Lx*.01} ${wr+H*.1} ${wx} ${wr}Z" fill="${wing}" stroke="${edge}" stroke-width=".6"/>`+
       `<path d="M${wx+Lx*.03} ${wr+H*.15}L${wx+Lx*.215} ${wr+H*.12}L${tx+Lx*.03} ${ty+H*.03}" fill="none" stroke="${wingD}" stroke-width="${Math.max(.7,H*.06)}"/>`+
       "";
    const tip=tipOf(m),ws=`stroke="${edge}" stroke-width=".4"`;let nav=[tx,ty];
