    {const ax=wx+Lx*.215,ay=wr+H*.12,bx=tx+Lx*.03,by=ty+H*.03;for(const t of [.15,.42,.68]){const fx=ax+(bx-ax)*t,fy=ay+(by-ay)*t;g+=`<ellipse cx="${(fx+H*.12).toFixed(2)}" cy="${(fy+H*.02).toFixed(2)}" rx="${(H*.22).toFixed(2)}" ry="${(H*.055).toFixed(2)}" transform="rotate(${(Math.atan2(by-ay,bx-ax)*180/Math.PI).toFixed(1)} ${fx.toFixed(2)} ${fy.toFixed(2)})" fill="${wingD}" stroke="${edge}" stroke-width=".3"/>`}}
