function drawChart(){
  const cv=$("#chart");if(!cv)return;const dpr=window.devicePixelRatio||1,W=cv.clientWidth,H=cv.clientHeight;
  cv.width=W*dpr;cv.height=H*dpr;const x=cv.getContext("2d");x.setTransform(dpr,0,0,dpr,0,0);
  const d=S.hist.slice(-180);if(d.length<2){x.fillStyle=cssv("--muted");x.font="13px Anuphan, sans-serif";x.fillText("กราฟจะขึ้นเมื่อผ่านไปสองสามวัน",8,H/2);return}
  let mn=Math.min(0,...d.map(p=>p.c)),mx=Math.max(...d.map(p=>p.c));if(mx===mn)mx=mn+1;
  const pl=46,pr=6,pt=8,pb=18,X=i=>pl+i/(d.length-1)*(W-pl-pr),Y=v=>pt+(mx-v)/(mx-mn)*(H-pt-pb);
  x.font="11px 'IBM Plex Mono', monospace";x.fillStyle=cssv("--muted");x.strokeStyle=cssv("--grid");x.lineWidth=1;x.textBaseline="middle";
  for(let i=0;i<=3;i++){const v=mn+(mx-mn)*i/3,y=Y(v);x.beginPath();x.moveTo(pl,y);x.lineTo(W-pr,y);x.stroke();x.fillText(money(v,true).replace("฿",""),2,y)}
  if(mn<0){x.strokeStyle=cssv("--bad");x.beginPath();x.moveTo(pl,Y(0));x.lineTo(W-pr,Y(0));x.stroke()}
  x.textBaseline="alphabetic";x.fillText(dateOf(d[0].d),pl,H-3);const lt=dateOf(d[d.length-1].d);x.fillText(lt,W-pr-x.measureText(lt).width,H-3);
  const col=cssv("--route");x.beginPath();d.forEach((p,i)=>i?x.lineTo(X(i),Y(p.c)):x.moveTo(X(i),Y(p.c)));
  x.strokeStyle=col;x.lineWidth=2;x.stroke();x.lineTo(X(d.length-1),Y(mn));x.lineTo(X(0),Y(mn));x.closePath();x.globalAlpha=.12;x.fillStyle=col;x.fill();x.globalAlpha=1;
  x.beginPath();x.arc(X(d.length-1),Y(d[d.length-1].c),3.5,0,7);x.fillStyle=cssv("--accent");x.fill();
}

/* ---------- loop ---------- */
function frame(now){
  const dt=Math.min(250,now-lastTick);lastTick=now;
  if(S&&!S.over&&!paused){acc+=dt*speed;
    while(acc>=DAY_MS){settleFlights(S.day+1-1e-7);settleShips(S.day+1-1e-7);acc-=DAY_MS;simDay();
      if(!sheetFn){if(tab==="home")refreshHome();else if(tab==="map")refreshMapTab();else renderView()}
      updateTop();if(S.over){showOver();break}}}
  if(S&&!S.over&&!paused){settleFlights(S.day+acc/DAY_MS);settleShips(S.day+acc/DAY_MS)}
  if(S&&!S.over&&now-(frame.mc||0)>1200){frame.mc=now;checkMissions();lvlCheck();msCheck();liveHome();dailyCheck();const rn=$("#rankno");if(rn){rn.textContent="#"+rank();const rp=$("#rankpanel");if(rp&&!rp.hidden&&!rp.querySelector("details[open]"))rp.innerHTML=rankPanelHTML()}}
  if(S&&afk&&pendingDec){const d=pendingDec;pendingDec=null;const i=d.c.length-1,msg=d.c[i][2]();addNews(`${d.e} ${msg} (AFK เลือกให้)`);afk.log.unshift(`${d.e} ${d.t}: เลือก "${d.c[i][0]}"`);save()}
  if(S&&afk&&now-(frame.ak||0)>500){frame.ak=now;afkTick()}
  if(S&&now-(frame.sn||0)>10000){frame.sn=now;S.seen=Date.now();save()}
  if(S&&pendingDec&&!sheetFn&&!S.over){const d=pendingDec;pendingDec=null;openDecision(d)}
  if(S&&tab==="money"&&!sheetFn&&now-(frame.lt||0)>400){frame.lt=now;const tp=$("#todayp");if(tp)tp.innerHTML=todayHTML()}
  if(S){animDay=S.day+acc/DAY_MS;if(!afk&&tab==="home"&&now-(frame.lb||0)>=110){frame.lb=now;liveBoard()}if(!afk&&(tab==="home"||tab==="map")&&$("#map")&&now-(frame.dm||0)>=31){frame.dm=now;drawMap()}
    if(tab==="map"&&now-(frame.hl||0)>500){frame.hl=now;const hd=$("#maphud");if(hd)hd.innerHTML=mapHudHTML()}
    const dt2=$("#dt");if(dt2){const mins=Math.floor((acc/DAY_MS)*1440/5)*5,tx=`วันที่ ${S.day+1} · ${dateOf(S.day)} · ${String(mins/60|0).padStart(2,"0")}:${String(mins%60).padStart(2,"0")} น.`;if(dt2.textContent!==tx)dt2.textContent=tx}
    const cs=$("#cs");if(cs){dispCash+=(S.cash-dispCash)*Math.min(1,dt/180);if(Math.abs(S.cash-dispCash)<1)dispCash=S.cash;cs.textContent=money(dispCash);cs.className="v "+(S.cash<0?"bad":"")}}
  requestAnimationFrame(frame)}
addEventListener("resize",()=>{if(S&&tab==="money")drawChart();if(S&&tab==="map")sizeFullMap()});
matchMedia("(prefers-color-scheme: dark)").addEventListener?.("change",()=>{if(S&&themePref()==="auto")renderView()});
/* ---------- light / dark mode: auto follows the device, or pin light or dark ---------- */
function themePref(){try{return localStorage.getItem("airline-theme")||"auto"}catch(e){return "auto"}}
function applyTheme(t){if(t==="auto")delete document.documentElement.dataset.theme;else document.documentElement.dataset.theme=t;
  const dark=t==="dark"||(t==="auto"&&matchMedia("(prefers-color-scheme: dark)").matches);document.documentElement.style.colorScheme=dark?"dark":"light"}
const THEMES=[["auto","🌓","ตามเครื่อง"],["light","☀️","สว่าง"],["dark","🌑","มืด"]];
function themeIcon(){const t=THEMES.find(x=>x[0]===themePref())||THEMES[0];return `<span aria-hidden="true">${t[1]}</span>`}
function cycleTheme(){const i=THEMES.findIndex(x=>x[0]===themePref()),n=THEMES[(i+1)%THEMES.length];try{localStorage.setItem("airline-theme",n[0])}catch(e){}
  applyTheme(n[0]);const b=$("#themebtn .mi");if(b)b.innerHTML=themeIcon();const tl=$("#themelbl");if(tl)tl.textContent="โหมดแสง: "+n[2];baseKey="";fogKey="";if(S)renderView();toast(`${n[1]} โหมด${n[2]}`)}
applyTheme(themePref());

S=load();if(!S)rollFate();else{dispCash=S.cash;seenNews=S.news.length?S.news[0].id:0}
renderApp();requestAnimationFrame(frame);
spHandleRedirect();
if(S)setTimeout(()=>awayCheck(S.seen),400);
let hiddenAt=0;
document.addEventListener("visibilitychange",()=>{if(!S)return;
  if(document.hidden){hiddenAt=Date.now();S.seen=hiddenAt;S.afkOn=!!afk;save()}
  else{if(afk)wakeOn();if(hiddenAt){const t=hiddenAt;hiddenAt=0;awayCheck(t)}}});
